const CACHE_PREFIX = 'prism-breaker-release-';
const CACHE_NAME = CACHE_PREFIX + VERSION;
const PIN_CACHE = 'prism-breaker-client-pins-v1';
const COMPLETE_PATH = '/__prism_pwa_complete__';
const paths = new Set(PRECACHE.map(asset => asset.path));
const pins = new Map();
let installing;
const absolute = path => new URL(path, self.location.origin).href;
const pinPath = id => absolute('/__prism_pwa_client__/' + encodeURIComponent(id));

async function complete(version) {
  return !!(await caches.match(absolute(COMPLETE_PATH), {cacheName: CACHE_PREFIX + version}));
}

async function rememberClient(id, version) {
  if (!id || (version !== 'network' && (!/^[a-f0-9]{20}$/.test(version) || !await complete(version)))) return false;
  pins.set(id, version);
  const store = await caches.open(PIN_CACHE);
  await store.put(pinPath(id), new Response(JSON.stringify({version}), {headers: {'Content-Type': 'application/json'}}));
  return true;
}

async function clientVersion(id) {
  if (!id) return VERSION;
  if (pins.has(id)) return pins.get(id);
  const record = await caches.match(pinPath(id), {cacheName: PIN_CACHE});
  if (record) {
    const {version} = await record.json();
    if (version === 'network' || (/^[a-f0-9]{20}$/.test(version) && await complete(version))) {
      pins.set(id, version);
      return version;
    }
  }
  await rememberClient(id, VERSION);
  return VERSION;
}

async function download(asset, cache) {
  const url = new URL(asset.path, self.location.origin);
  url.searchParams.set('__prism_release', VERSION);
  const response = await fetch(url.href, {cache: 'reload', credentials: 'same-origin'});
  if (response.status !== 200 || response.type === 'opaque' || response.redirected) {
    throw new Error('Offline download failed: ' + asset.path);
  }
  if (asset.path === '/index.html') {
    // Pagelove serializes HTML on write; verify its release identity instead of raw bytes.
    const html = await response.clone().text();
    const marker = new RegExp('<meta\\b(?=[^>]*\\bname=["\']prism-release["\'])(?=[^>]*\\bcontent=["\']' + VERSION + '["\'])[^>]*>', 'i');
    if (!response.headers.get('content-type')?.includes('text/html') || !marker.test(html)) {
      throw new Error('Offline document belongs to a different release');
    }
  } else {
    const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
    const hash = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
    if (hash !== asset.sha256) throw new Error('Offline asset changed during download: ' + asset.path);
  }
  await cache.put(absolute(asset.path), response);
}

async function prepareOfflineCache() {
  if (installing) return installing;
  installing = (async () => {
    if (await complete(VERSION)) return;
    const cache = await caches.open(CACHE_NAME);
    try {
      // Bound simultaneous downloads and wait for every write before removing a failed cache.
      for (let offset = 0; offset < PRECACHE.length; offset += 6) {
        const batch = await Promise.allSettled(PRECACHE.slice(offset, offset + 6).map(asset => download(asset, cache)));
        const failed = batch.find(result => result.status === 'rejected');
        if (failed) throw failed.reason;
      }
      await cache.put(absolute(COMPLETE_PATH), new Response(JSON.stringify({version: VERSION, savedAt: Date.now(), files: PRECACHE.length}), {headers: {'Content-Type': 'application/json'}}));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })();
  try { await installing; } finally { installing = null; }
}

self.addEventListener('install', event => {
  // Updates intentionally wait. The start screen offers the explicit restart action.
  event.waitUntil(prepareOfflineCache());
});

async function pruneUnusedReleases() {
  const windows = await self.clients.matchAll({type: 'window', includeUncontrolled: true});
  const store = await caches.open(PIN_CACHE);
  const inUse = new Set([VERSION]);
  const liveIds = new Set(windows.map(client => client.id));
  let unknownClient = false;
  for (const client of windows) {
    const record = await store.match(pinPath(client.id));
    if (!record) { unknownClient = true; continue; }
    inUse.add((await record.json()).version);
  }
  // An unregistered or older page may still be loading: preserve its possible release.
  if (unknownClient) return;
  const releases = [];
  for (const name of await caches.keys()) {
    if (!name.startsWith(CACHE_PREFIX)) continue;
    const marker = await caches.match(absolute(COMPLETE_PATH), {cacheName: name});
    if (marker) releases.push({name, ...await marker.json()});
  }
  // Retain one previous release as a fallback, plus every release used by an open tab.
  releases.sort((a, b) => b.savedAt - a.savedAt);
  for (const release of releases.slice(0, 2)) inUse.add(release.version);
  for (const release of releases) if (!inUse.has(release.version)) await caches.delete(release.name);
  for (const request of await store.keys()) {
    const id = decodeURIComponent(new URL(request.url).pathname.split('/').pop());
    if (!liveIds.has(id)) await store.delete(request);
  }
}

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    await pruneUnusedReleases();
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  const data = event.data;
  if (!data || typeof data !== 'object') return;
  if (data.type === 'SKIP_WAITING') {
    event.waitUntil(self.skipWaiting());
  } else if (data.type === 'CLIENT_VERSION') {
    event.waitUntil((async () => {
      const ready = await rememberClient(event.source?.id, data.version);
      event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: data.version, ready});
    })());
  } else if (data.type === 'GET_STATUS') {
    event.waitUntil((async () => {
      const version = await clientVersion(event.source?.id);
      event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: version, ready: await complete(version)});
    })());
  } else if (data.type === 'REPAIR_CACHE') {
    event.waitUntil((async () => {
      try {
        if (data.version !== VERSION) throw new Error('A newer game release is available. Reload to download it.');
        await prepareOfflineCache();
        await rememberClient(event.source?.id, VERSION);
        event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: VERSION, ready: true});
      } catch (error) {
        event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: data.version, ready: false, error: error.message});
      }
    })());
  }
});

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  // Selector responses, score reads and writes remain exclusively owned by Pagelove.
  if (request.method !== 'GET' || url.origin !== self.location.origin || request.headers.has('range') || url.pathname.startsWith('/__qa/') || url.pathname === '/scores.html' || url.pathname === '/worlds.html') return;
  const navigation = request.mode === 'navigate' && (url.pathname === '/' || url.pathname === '/index.html');
  // A still-open older tab may request a lazy module removed from the latest release.
  const staticPath = url.pathname !== '/sw.js' && (/^\/assets\//.test(url.pathname) || /^\/vendor\//.test(url.pathname) || /\.(?:js|css|webmanifest|ico|svg|png)$/.test(url.pathname));
  if (!navigation && !paths.has(url.pathname) && !staticPath) return;
  event.respondWith((async () => {
    const version = navigation ? VERSION : await clientVersion(event.clientId);
    if (navigation && event.resultingClientId) await rememberClient(event.resultingClientId, version);
    // Storage can be evicted independently of registration. Only a newly loaded document
    // may recover from the network; an already-running release must never mix its modules.
    if (version === 'network') return fetch(request);
    const cached = await caches.match(absolute(navigation ? '/index.html' : url.pathname), {cacheName: CACHE_PREFIX + version});
    if (cached) return cached;
    if (navigation || paths.has(url.pathname)) {
      const cache = await caches.open(CACHE_PREFIX + version);
      await cache.delete(absolute(COMPLETE_PATH));
    }
    if (navigation) {
      try {
        const response = await fetch(request);
        if (response.ok && event.resultingClientId) await rememberClient(event.resultingClientId, 'network');
        return response;
      } catch { /* A plain offline message below still permits a later online reload. */ }
    }
    // Never splice a new network module into an older running game if storage was evicted.
    return new Response('The offline game download is incomplete. Reconnect and reload Prism Breaker.', {status: 503, headers: {'Content-Type': 'text/plain; charset=utf-8'}});
  })());
});
